<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\UserAcceptedTermnsOfUse\Domain\ValueObject\Accessor\UserAcceptedTermnsOfUseUserAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserAcceptedTermnsOfUseUserAccessor trait.
 *
 * Covers null default, string/VO assignment via withUser,
 * getUser/user accessors, and isUserChanged with/without original.
 */
class UserAcceptedTermnsOfUseUserAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withUser creates a new instance with the User set
     * from a string value, and getUser returns the primitive string.
     */
    public function testWithUserFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserAcceptedTermnsOfUseUserAccessorUnitTest();

        // Act
        $result = $holder->withUser(new UserRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new UserRef('one'), $result->getUser());
    }
    /**
     * Asserts that withuser has access to the value object
     * from a string value, and getUser returns the primitive string.
     */
    public function testWithUserFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserAcceptedTermnsOfUseUserAccessorUnitTest();

        // Act
        $result = $holder->withUser(new UserRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new UserRef('one'), $result->user()->value());
    }
    public function testChangedUser(): void
    {
        // Arrange
        $holder = new ImplWithUserAcceptedTermnsOfUseUserAccessorUnitTest()->withUser(new UserRef('one'));
        $original = $holder->withUser(new UserRef('one'));
        $same = $holder->withUser(new UserRef('one'));
        $modified = $holder->withUser(new UserRef('other'));

        // Act
        $withSame = $original->isUserChanged($same);
        $withDiferent = $original->isUserChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserAcceptedTermnsOfUseUserAccessorUnitTest
{
    use UserAcceptedTermnsOfUseUserAccessor;
}
